#!/usr/bin/env python3
"""Offline auditor for a synthetic QUIC v1 receiver model.

Reads one JSON document on stdin, replays every trace through the finite
receiver state machine described by the task contract, and writes one JSON
document on stdout.
"""
import sys
import json
import re
import bisect

MAXN = 4611686018427387903          # 2**62 - 1
MAXT = 1000000000000                # event timestamp domain
LIM_TRACES = 32
LIM_EVENTS = 20000
LIM_PACKETS = 20000
LIM_FRAMES = 60000
LIM_DATA = 2 * 1024 * 1024
LIM_HEXCHARS = 4096                 # 2048 decoded bytes
LIM_RANGES = 32
LIM_DG_PKTS = 16
LIM_PKT_FRAMES = 64

INVALID_OUT = '{"error":"INVALID_INPUT"}'

LEVELS = ("I", "H", "Z", "A")
CLEVELS = ("I", "H", "A")
# Z and A share the application packet number space
SPACE_OF = {"I": "I", "H": "H", "Z": "A", "A": "A"}

# frame tag -> tuple of levels where the frame is whitelisted
ALLOWED = {
    "pad": ("I", "H", "Z", "A"),
    "ping": ("I", "H", "Z", "A"),
    "ack": ("I", "H", "A"),
    "cry": ("I", "H", "A"),
    "str": ("Z", "A"),
    "rs": ("Z", "A"),
    "ss": ("Z", "A"),
    "cl0": ("I", "H", "Z", "A"),      # CLOSE with app == False
    "cl1": ("Z", "A"),                # CLOSE with app == True
    "hd": (),                         # the modelled receiver is a server
}

JSON_WS = " \t\n\r"


class Bad(Exception):
    """Raised for every invalid input."""


ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}\Z")
HEX_RE = re.compile(r"[0-9a-f]*\Z")


def _pairs_hook(pairs):
    obj = {}
    for k, v in pairs:
        if k in obj:
            raise Bad()
        obj[k] = v
    return obj


def _reject_const(_name):
    raise Bad()


DECODER = json.JSONDecoder(parse_constant=_reject_const,
                           object_pairs_hook=_pairs_hook)


# --------------------------------------------------------------------------
# input validation (also builds the compact internal representation)
# --------------------------------------------------------------------------

def _keys_exact(obj, required):
    if type(obj) is not dict:
        raise Bad()
    if len(obj) != len(required):
        raise Bad()
    for k in required:
        if k not in obj:
            raise Bad()
    return obj


def _dom_int(v):
    return type(v) is int and 0 <= v <= MAXN


def _bounded_int(v, hi):
    return type(v) is int and 0 <= v <= hi


def _parse_ranges_shape(v):
    """Grammar level checks for a RANGES value (ordering is a protocol matter)."""
    if type(v) is not list:
        raise Bad()
    if len(v) > LIM_RANGES:
        raise Bad()
    out = []
    for item in v:
        if type(item) is not list or len(item) != 2:
            raise Bad()
        lo = item[0]
        hi = item[1]
        if not _dom_int(lo) or not _dom_int(hi):
            raise Bad()
        out.append((lo, hi))
    return out


def _parse_ranges_cfg(v):
    """CONFIG ranges additionally ascend and are disjoint and nonadjacent."""
    out = _parse_ranges_shape(v)
    prev_hi = None
    for lo, hi in out:
        if lo > hi:
            raise Bad()
        if prev_hi is not None and lo <= prev_hi + 1:
            raise Bad()
        prev_hi = hi
    return out


def _parse_data_hex(v, counts):
    if type(v) is not str:
        raise Bad()
    n = len(v)
    if n > LIM_HEXCHARS or (n & 1) or not HEX_RE.match(v):
        raise Bad()
    data = bytes.fromhex(v)
    counts[3] += n // 2
    if counts[3] > LIM_DATA:
        raise Bad()
    return data


FRAME_TYPES = ("PADDING", "PING", "ACK", "CRYPTO", "STREAM", "RESET_STREAM",
               "STOP_SENDING", "CLOSE", "HANDSHAKE_DONE", "UNKNOWN")
FRAME_TYPES = frozenset(FRAME_TYPES)


def _parse_frame(f, counts):
    if type(f) is not dict:
        raise Bad()
    ty = f.get("type")
    if type(ty) is not str or ty not in FRAME_TYPES:
        raise Bad()
    if ty == "PADDING":
        _keys_exact(f, ("type",))
        return ("pad",)
    if ty == "PING":
        _keys_exact(f, ("type",))
        return ("ping",)
    if ty == "UNKNOWN":
        _keys_exact(f, ("type",))
        return ("un",)
    if ty == "HANDSHAKE_DONE":
        _keys_exact(f, ("type",))
        return ("hd",)
    if ty == "ACK":
        _keys_exact(f, ("type", "ranges"))
        return ("ack", tuple(_parse_ranges_shape(f["ranges"])))
    if ty == "CRYPTO":
        _keys_exact(f, ("type", "offset", "data_hex"))
        off = f["offset"]
        if not _dom_int(off):
            raise Bad()
        return ("cry", off, _parse_data_hex(f["data_hex"], counts))
    if ty == "STREAM":
        _keys_exact(f, ("type", "id", "offset", "data_hex", "fin"))
        sid = f["id"]
        off = f["offset"]
        if not _dom_int(sid) or not _dom_int(off):
            raise Bad()
        if type(f["fin"]) is not bool:
            raise Bad()
        return ("str", sid, off, _parse_data_hex(f["data_hex"], counts),
                f["fin"])
    if ty == "RESET_STREAM":
        _keys_exact(f, ("type", "id", "final_size"))
        sid = f["id"]
        size = f["final_size"]
        if not _dom_int(sid) or not _dom_int(size):
            raise Bad()
        return ("rs", sid, size)
    if ty == "STOP_SENDING":
        _keys_exact(f, ("type", "id"))
        sid = f["id"]
        if not _dom_int(sid):
            raise Bad()
        return ("ss", sid)
    # CLOSE
    _keys_exact(f, ("type", "app", "code"))
    if type(f["app"]) is not bool:
        raise Bad()
    code = f["code"]
    if not _dom_int(code):
        raise Bad()
    return ("cl", f["app"], code)


def _parse_packet(p, counts):
    _keys_exact(p, ("level", "pn", "auth", "frames"))
    lvl = p["level"]
    if type(lvl) is not str or lvl not in LEVELS:
        raise Bad()
    if not _dom_int(p["pn"]):
        raise Bad()
    if type(p["auth"]) is not bool:
        raise Bad()
    frames = p["frames"]
    if type(frames) is not list or len(frames) > LIM_PKT_FRAMES:
        raise Bad()
    counts[1] += 1
    if counts[1] > LIM_PACKETS:
        raise Bad()
    out = []
    for fr in frames:
        counts[2] += 1
        if counts[2] > LIM_FRAMES:
            raise Bad()
        out.append(_parse_frame(fr, counts))
    return (lvl, SPACE_OF[lvl], p["pn"], p["auth"], tuple(out))


def _parse_event(e, counts, prev_t):
    if type(e) is not dict:
        raise Bad()
    ty = e.get("op")
    if type(ty) is not str:
        raise Bad()
    if "t" not in e:
        raise Bad()
    t = e["t"]
    if not _bounded_int(t, MAXT) or t < prev_t:
        raise Bad()
    if ty == "tick":
        _keys_exact(e, ("t", "op"))
        counts[0] += 1
        return ("tk", t)
    if ty == "key":
        _keys_exact(e, ("t", "op", "level", "action"))
        lvl = e["level"]
        act = e["action"]
        if type(lvl) is not str or lvl not in LEVELS:
            raise Bad()
        if act != "install" and act != "discard":
            raise Bad()
        counts[0] += 1
        return ("k", t, lvl, act)
    if ty == "datagram":
        _keys_exact(e, ("t", "op", "bytes", "packets"))
        size = e["bytes"]
        if not _bounded_int(size, 65535):
            raise Bad()
        pkts = e["packets"]
        if type(pkts) is not list or not (1 <= len(pkts) <= LIM_DG_PKTS):
            raise Bad()
        parsed = tuple(_parse_packet(p, counts) for p in pkts)
        counts[0] += 1
        return ("dg", t, size, parsed)
    raise Bad()


def _parse_config(c):
    cfg = _keys_exact(c, ("early", "overlap", "buffer_packets", "idle_ms",
                          "max_streams_bidi", "max_streams_uni",
                          "max_stream_data", "max_data", "crypto_limit",
                          "sent"))
    early = cfg["early"]
    if type(early) is not bool:
        raise Bad()
    ov = cfg["overlap"]
    if ov != "reject" and ov != "first":
        raise Bad()
    if not _bounded_int(cfg["buffer_packets"], 1024):
        raise Bad()
    if not _bounded_int(cfg["idle_ms"], 1000000000):
        raise Bad()
    if not _bounded_int(cfg["max_streams_bidi"], 1024):
        raise Bad()
    if not _bounded_int(cfg["max_streams_uni"], 1024):
        raise Bad()
    if not _bounded_int(cfg["max_stream_data"], 65536):
        raise Bad()
    if not _dom_int(cfg["max_data"]):
        raise Bad()
    if not _bounded_int(cfg["crypto_limit"], 65536):
        raise Bad()
    sent = _keys_exact(cfg["sent"], ("I", "H", "A"))
    spaces = {}
    for lvl in CLEVELS:
        rngs = _parse_ranges_cfg(sent[lvl])
        spaces[lvl] = (tuple(r[0] for r in rngs), rngs)
    return {
        "early": early,
        "reject": ov == "reject",
        "buffer_packets": cfg["buffer_packets"],
        "idle_ms": cfg["idle_ms"],
        "msb": cfg["max_streams_bidi"],
        "msu": cfg["max_streams_uni"],
        "msd": cfg["max_stream_data"],
        "max_data": cfg["max_data"],
        "crypto_limit": cfg["crypto_limit"],
        "sent": spaces,
    }


def _parse_trace(tr, counts):
    t = _keys_exact(tr, ("id", "config", "events"))
    tid = t["id"]
    if type(tid) is not str or not ID_RE.match(tid):
        raise Bad()
    cfg = _parse_config(t["config"])
    events = t["events"]
    if type(events) is not list:
        raise Bad()
    out = []
    prev_t = 0
    for e in events:
        ev = _parse_event(e, counts, prev_t)
        prev_t = ev[1]
        out.append(ev)
        if counts[0] > LIM_EVENTS:
            raise Bad()
    return (tid, cfg, tuple(out))


def parse_document(text):
    """Parse and validate; raises Bad on any invalid input."""
    n = len(text)
    i = 0
    while i < n and text[i] in JSON_WS:
        i += 1
    if i == n:
        raise Bad()
    obj, end = DECODER.raw_decode(text, i)
    while end < n and text[end] in JSON_WS:
        end += 1
    if end != n:
        raise Bad()
    root = _keys_exact(obj, ("version", "traces"))
    if not _bounded_int(root["version"], MAXN) or root["version"] != 1:
        raise Bad()
    traces = root["traces"]
    if type(traces) is not list:
        raise Bad()
    if len(traces) > LIM_TRACES:
        raise Bad()
    counts = [0, 0, 0, 0]          # events, packets, frames, decoded bytes
    seen = set()
    out = []
    for tr in traces:
        item = _parse_trace(tr, counts)
        if item[0] in seen:
            raise Bad()
        seen.add(item[0])
        out.append(item)
    return out


# --------------------------------------------------------------------------
# byte range bookkeeping
#
# ivs is a list of (start, end, bytes) tuples kept sorted by start and
# pairwise disjoint.  Already stored bytes are never overwritten, so an
# insertion only ever fills holes; that keeps undo (transaction rollback)
# cheap and exact.
# --------------------------------------------------------------------------

def store_insert(ivs, a, data, reject, journal):
    n = len(data)
    if n == 0:
        return True
    b = a + n
    i0 = bisect.bisect_left(ivs, (a,))
    if i0 > 0 and ivs[i0 - 1][1] > a:
        i0 -= 1
    i = i0
    last = len(ivs)
    holes = []
    conflict = False
    while i < last:
        s = ivs[i][0]
        if s >= b:
            break
        e = ivs[i][1]
        d = ivs[i][2]
        lo = s if s > a else a
        hi = e if e < b else b
        if d[lo - s:hi - s] != data[lo - a:hi - a]:
            conflict = True
        i += 1
    if conflict and reject:
        return False
    # recompute the holes (a full-overlap scan is cheap; conflicts may stop it)
    pos = a
    i = i0
    covered = []
    while i < last:
        s = ivs[i][0]
        if s >= b:
            break
        e = ivs[i][1]
        lo = s if s > a else a
        hi = e if e < b else b
        covered.append((lo, hi))
        i += 1
    gaps = []
    pos = a
    for lo, hi in covered:
        if lo > pos:
            gaps.append((pos, lo, data[pos - a:lo - a]))
        pos = hi
    if b > pos:
        gaps.append((pos, b, data[pos - a:b - a]))
    if not gaps:
        return True
    merged = []
    j = i0
    k = 0
    ng = len(gaps)
    while j < i or k < ng:
        if k >= ng or (j < i and ivs[j][0] < gaps[k][0]):
            merged.append(ivs[j])
            j += 1
        else:
            merged.append(gaps[k])
            k += 1
    journal.append((3, ivs, i0, len(merged), ivs[i0:i]))
    ivs[i0:i] = merged
    return True


def store_deliver(ivs, pos):
    """Bytes of the contiguous run that starts at pos (may be empty)."""
    idx = bisect.bisect_left(ivs, (pos,))
    if idx > 0 and ivs[idx - 1][1] > pos:
        idx -= 1
    parts = None
    last = len(ivs)
    while idx < last:
        s, e, d = ivs[idx]
        if s > pos:
            break
        if e > pos:
            if parts is None:
                parts = [d[pos - s:e - s]]
            else:
                parts.append(d[pos - s:e - s])
            pos = e
        idx += 1
    if parts is None:
        return None
    if len(parts) == 1:
        return parts[0]
    return b"".join(parts)


# --------------------------------------------------------------------------
# replay
# --------------------------------------------------------------------------

class Stream(object):
    __slots__ = ("sid", "highest", "final", "reset", "stopped", "ivs",
                 "delivered")

    def __init__(self, sid):
        self.sid = sid
        self.highest = 0
        self.final = None
        self.reset = False
        self.stopped = False
        self.ivs = []
        self.delivered = bytearray()


class CStore(object):
    __slots__ = ("ivs", "contig", "highest")

    def __init__(self):
        self.ivs = []
        self.contig = bytearray()
        self.highest = 0


class Replay(object):
    def __init__(self, tid, cfg, events):
        self.id = tid
        self.events = events
        self.early = cfg["early"]
        self.reject = cfg["reject"]
        self.bufmax = cfg["buffer_packets"]
        self.idle_ms = cfg["idle_ms"]
        self.msb = cfg["msb"]
        self.msu = cfg["msu"]
        self.msd = cfg["msd"]
        self.max_data = cfg["max_data"]
        self.clim = cfg["crypto_limit"]
        self.sent = cfg["sent"]

        self.keys = {"I": "live", "H": "absent",
                     "Z": "live" if self.early else "absent", "A": "absent"}
        self.queue = {"I": [], "H": [], "Z": [], "A": []}
        self.qcount = 0
        self.pnsets = {"I": set(), "H": set(), "A": set()}
        self.streams = {}
        self.cs = {"I": CStore(), "H": CStore(), "A": CStore()}
        self.received_total = 0

        self.state = "open"
        self.code = None
        self.at_ms = None
        self.source = None
        self.peer_code = None
        self.last_activity = 0
        self.results = []

        self.txid = 0
        self.snap_st = {}
        self.snap_cs = {}
        self.journal = []

    # ---- transaction helpers -------------------------------------------

    def snapshot_stream(self, st):
        if self.snap_st.get(st.sid) != self.txid:
            self.snap_st[st.sid] = self.txid
            self.journal.append((0, st, st.highest, st.final, st.reset,
                                 st.stopped, len(st.delivered)))

    def snapshot_cstore(self, lvl):
        if self.snap_cs.get(lvl) != self.txid:
            self.snap_cs[lvl] = self.txid
            cs = self.cs[lvl]
            self.journal.append((1, cs, lvl, cs.highest, len(cs.contig)))

    def get_stream(self, sid):
        st = self.streams.get(sid)
        if st is None:
            st = Stream(sid)
            self.streams[sid] = st
            self.journal.append((2, sid))
        return st

    def rollback(self, saved_total):
        j = self.journal
        for k in range(len(j) - 1, -1, -1):
            ent = j[k]
            tag = ent[0]
            if tag == 0:
                st = ent[1]
                st.highest = ent[2]
                st.final = ent[3]
                st.reset = ent[4]
                st.stopped = ent[5]
                dl = ent[6]
                if len(st.delivered) != dl:
                    del st.delivered[dl:]
            elif tag == 1:
                cs = self.cs[ent[2]]
                cs.highest = ent[3]
                cl = ent[4]
                if len(cs.contig) != cl:
                    del cs.contig[cl:]
            elif tag == 2:
                del self.streams[ent[1]]
            else:
                ivs = ent[1]
                i0 = ent[2]
                ivs[i0:i0 + ent[3]] = ent[4]
        self.journal = []
        self.snap_st = {}
        self.snap_cs = {}
        self.received_total = saved_total

    # ---- result / termination ------------------------------------------

    def res(self, ei, pi, status, reason, at, frame):
        self.results.append((ei, pi, status, reason, at, frame))

    def terminate(self, state, code, at, source, peer_code):
        self.state = state
        self.code = code
        self.at_ms = at
        self.source = source
        self.peer_code = peer_code
        for lvl in LEVELS:
            self.drop_queue(lvl, "CONNECTION_CLOSED", at)

    def drop_queue(self, lvl, reason, at):
        items = self.queue[lvl]
        if not items:
            return
        self.queue[lvl] = []
        self.qcount -= len(items)
        for item in items:
            self.res(item[0], item[1], "dropped", reason, at, None)

    # ---- events ---------------------------------------------------------

    def run(self):
        ei = 0
        for ev in self.events:
            kind = ev[0]
            t = ev[1]
            if self.state == "open" and self.idle_ms:
                deadline = self.last_activity + self.idle_ms
                if t >= deadline:
                    self.terminate("idle", "IDLE_TIMEOUT", deadline,
                                   (ei, None, None), None)
            if self.state == "open":
                if kind == "k":
                    self.do_key(ev, t)
                elif kind == "dg":
                    self.do_datagram(ei, ev)
            ei += 1
        for lvl in LEVELS:
            for item in self.queue[lvl]:
                self.res(item[0], item[1], "buffered", "NO_KEYS", item[2],
                         None)
        self.queue = {"I": [], "H": [], "Z": [], "A": []}
        self.qcount = 0

    def do_key(self, ev, t):
        lvl = ev[2]
        if ev[3] == "discard":
            self.keys[lvl] = "discarded"
            self.drop_queue(lvl, "KEYS_DISCARDED", t)
        elif self.keys[lvl] == "absent":
            self.keys[lvl] = "live"
            items = self.queue[lvl]
            if items:
                self.queue[lvl] = []
                self.qcount -= len(items)
                for item in items:
                    if self.state != "open":
                        self.res(item[0], item[1], "dropped",
                                 "CONNECTION_CLOSED", t, None)
                        continue
                    self.handle_packet(item[0], item[1], item[3], t)

    def do_datagram(self, ei, ev):
        t = ev[1]
        size = ev[2]
        pkts = ev[3]
        n = len(pkts)
        if self.state == "open":
            for pi in range(n - 1):
                if pkts[pi][0] == "A":
                    for pj in range(n):
                        self.res(ei, pj, "dropped", "LAYOUT", t, None)
                    return
        for pi in range(n):
            pkt = pkts[pi]
            if self.state != "open":
                self.res(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
                continue
            lvl = pkt[0]
            if lvl == "I" and size < 1200:
                self.res(ei, pi, "dropped", "INITIAL_TOO_SMALL", t, None)
                continue
            if lvl == "Z" and not self.early:
                self.res(ei, pi, "dropped", "EARLY_REJECTED", t, None)
                continue
            ks = self.keys[lvl]
            if ks == "discarded":
                self.res(ei, pi, "dropped", "KEYS_DISCARDED", t, None)
                continue
            if ks == "absent":
                if self.qcount < self.bufmax:
                    self.queue[lvl].append((ei, pi, t, pkt))
                    self.qcount += 1
                else:
                    self.res(ei, pi, "dropped", "BUFFER_FULL", t, None)
                continue
            self.handle_packet(ei, pi, pkt, t)

    # ---- packets --------------------------------------------------------

    def handle_packet(self, ei, pi, pkt, t):
        lvl, space, pn, auth, frames = pkt
        if not auth:
            self.res(ei, pi, "dropped", "AUTH", t, None)
            return
        pset = self.pnsets[space]
        if pn in pset:
            self.res(ei, pi, "duplicate", "DUPLICATE", t, None)
            return
        if not frames:
            self.packet_error(ei, pi, t, "FRAME_ENCODING_ERROR", None)
            return
        for fi in range(len(frames)):
            if frames[fi][0] == "un":
                self.packet_error(ei, pi, t, "FRAME_ENCODING_ERROR", fi)
                return
        ok_levels = ALLOWED
        for fi in range(len(frames)):
            tag = frames[fi][0]
            if tag == "cl":
                tag = "cl1" if frames[fi][1] else "cl0"
            if lvl not in ok_levels[tag]:
                self.packet_error(ei, pi, t, "PROTOCOL_VIOLATION", fi)
                return
        self.txid += 1
        self.journal = []
        self.snap_st = {}
        self.snap_cs = {}
        saved_total = self.received_total
        close_fi = -1
        for fi in range(len(frames)):
            fr = frames[fi]
            tag = fr[0]
            if tag == "pad" or tag == "ping" or tag == "hd":
                continue
            if tag == "cl":
                close_fi = fi
                break
            if tag == "ack":
                err = self.frame_ack(fr, space, fi)
            elif tag == "cry":
                err = self.frame_crypto(fr, lvl, fi)
            elif tag == "str":
                err = self.frame_stream(fr, fi)
            elif tag == "rs":
                err = self.frame_reset(fr, fi)
            else:
                err = self.frame_stop(fr, fi)
            if err is not None:
                self.rollback(saved_total)
                self.packet_error(ei, pi, t, err, fi)
                return
        pset.add(pn)
        self.last_activity = t
        self.res(ei, pi, "accepted", "OK", t, None)
        if close_fi >= 0:
            fr = frames[close_fi]
            if fr[1]:
                name = "PEER_APPLICATION_CLOSE"
            else:
                name = "PEER_TRANSPORT_CLOSE"
            self.terminate("closed", name, t, (ei, pi, close_fi), fr[2])

    def packet_error(self, ei, pi, t, code, frame):
        self.res(ei, pi, "error", code, t, frame)
        self.terminate("closed", code, t, (ei, pi, frame), None)

    # ---- frames ---------------------------------------------------------

    def frame_ack(self, fr, space, fi):
        rngs = fr[1]
        if not rngs:
            return "FRAME_ENCODING_ERROR"
        prev_hi = None
        for lo, hi in rngs:
            if lo > hi:
                return "FRAME_ENCODING_ERROR"
            if prev_hi is not None and lo <= prev_hi + 1:
                return "FRAME_ENCODING_ERROR"
            prev_hi = hi
        starts, rlist = self.sent[space]
        for lo, hi in rngs:
            idx = bisect.bisect_right(starts, lo) - 1
            if idx < 0 or rlist[idx][1] < hi:
                return "PROTOCOL_VIOLATION"
        return None

    def frame_crypto(self, fr, lvl, fi):
        off = fr[1]
        data = fr[2]
        end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        self.snapshot_cstore(lvl)
        cs = self.cs[lvl]
        if end > self.clim:
            return "CRYPTO_BUFFER_EXCEEDED"
        if end > cs.highest:
            cs.highest = end
        if data:
            if not store_insert(cs.ivs, off, data, self.reject, self.journal):
                return "PROTOCOL_VIOLATION"
            chunk = store_deliver(cs.ivs, len(cs.contig))
            if chunk:
                cs.contig += chunk
        return None

    def _stream_common(self, sid, fi, want_bidi):
        """Direction and stream-count checks; returns (stream, error)."""
        mod = sid & 3
        if want_bidi:
            if mod != 0:
                return None, "STREAM_STATE_ERROR"
            limit = self.msb
        else:
            if mod != 0 and mod != 2:
                return None, "STREAM_STATE_ERROR"
            limit = self.msb if mod == 0 else self.msu
        if sid // 4 + 1 > limit:
            return None, "STREAM_LIMIT_ERROR"
        st = self.get_stream(sid)
        self.snapshot_stream(st)
        return st, None

    def frame_stream(self, fr, fi):
        sid = fr[1]
        off = fr[2]
        data = fr[3]
        fin = fr[4]
        st, err = self._stream_common(sid, fi, False)
        if st is None:
            return err
        end = off + len(data)
        if end > MAXN:
            return "FRAME_ENCODING_ERROR"
        final = st.final
        if final is not None and (end > final or (fin and end != final)):
            return "FINAL_SIZE_ERROR"
        if fin and end < st.highest:
            return "FINAL_SIZE_ERROR"
        if end > self.msd:
            return "FLOW_CONTROL_ERROR"
        if end > st.highest:
            delta = end - st.highest
            if self.received_total + delta > self.max_data:
                return "FLOW_CONTROL_ERROR"
            st.highest = end
            self.received_total += delta
        if not st.reset:
            if data and not store_insert(st.ivs, off, data, self.reject,
                                         self.journal):
                return "PROTOCOL_VIOLATION"
            chunk = store_deliver(st.ivs, len(st.delivered))
            if chunk:
                st.delivered += chunk
        if fin:
            st.final = end
        return None

    def frame_reset(self, fr, fi):
        sid = fr[1]
        size = fr[2]
        st, err = self._stream_common(sid, fi, False)
        if st is None:
            return err
        final = st.final
        if final is not None and final != size:
            return "FINAL_SIZE_ERROR"
        if size < st.highest:
            return "FINAL_SIZE_ERROR"
        if size > self.msd:
            return "FLOW_CONTROL_ERROR"
        if size > st.highest:
            delta = size - st.highest
            if self.received_total + delta > self.max_data:
                return "FLOW_CONTROL_ERROR"
            st.highest = size
            self.received_total += delta
        st.final = size
        st.reset = True
        return None

    def frame_stop(self, fr, fi):
        sid = fr[1]
        st, err = self._stream_common(sid, fi, True)
        if st is None:
            return err
        st.stopped = True
        return None

    # ---- output ---------------------------------------------------------

    def result(self):
        results = self.results
        results.sort(key=lambda r: (r[0], r[1]))
        pkts = []
        for (ei, pi, status, reason, at, frame) in results:
            pkts.append({"event": ei, "packet": pi, "status": status,
                         "reason": reason, "at_ms": at, "frame": frame})
        if self.state == "open":
            conn = {"state": "open", "code": None, "at_ms": None,
                    "source": None, "peer_code": None,
                    "last_activity_ms": self.last_activity}
        else:
            src = {"event": self.source[0], "packet": self.source[1],
                   "frame": self.source[2]}
            conn = {"state": self.state, "code": self.code,
                    "at_ms": self.at_ms, "source": src,
                    "peer_code": self.peer_code,
                    "last_activity_ms": self.last_activity}
        streams = []
        for sid in sorted(self.streams):
            st = self.streams[sid]
            streams.append({"id": sid, "highest": st.highest,
                            "final_size": st.final, "reset": st.reset,
                            "stopped": st.stopped,
                            "delivered_hex": bytes(st.delivered).hex()})
        crypto = []
        for lvl in CLEVELS:
            cs = self.cs[lvl]
            crypto.append({"level": lvl, "highest": cs.highest,
                           "contiguous_hex": bytes(cs.contig).hex()})
        return {"id": self.id, "packets": pkts, "connection": conn,
                "keys": {"I": self.keys["I"], "H": self.keys["H"],
                         "Z": self.keys["Z"], "A": self.keys["A"]},
                "received_total": self.received_total,
                "streams": streams, "crypto": crypto}


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------

def main():
    try:
        data = sys.stdin.buffer.read()
    except Exception:
        sys.stdout.write(INVALID_OUT)
        return 0
    try:
        text = data.decode("utf-8")
    except Exception:
        sys.stdout.write(INVALID_OUT)
        return 0
    try:
        traces = parse_document(text)
    except Exception:
        sys.stdout.write(INVALID_OUT)
        return 0
    text = None
    data = None
    try:
        out = []
        for (tid, cfg, events) in traces:
            rp = Replay(tid, cfg, events)
            rp.run()
            out.append(rp.result())
        traces = None
        doc = json.dumps({"version": 1, "results": out},
                         separators=(",", ":"))
    except Exception as exc:            # defensive: never crash silently
        sys.stderr.write("internal error: %r\n" % (exc,))
        sys.stdout.write(INVALID_OUT)
        return 0
    sys.stdout.write(doc)
    return 0


if __name__ == "__main__":
    sys.exit(main())
