"""Deliberately naive reference implementation of the audit contract.

Written straight from the specification text: no transaction journal, whole
state snapshots for rollback, per-byte dicts for reassembly.  Only used to
cross-check the fast implementation on small inputs.
"""
import copy

MAXN = 4611686018427387903
LEVELS = ("I", "H", "Z", "A")

WL = {
    "PADDING": ("I", "H", "Z", "A"),
    "PING": ("I", "H", "Z", "A"),
    "ACK": ("I", "H", "A"),
    "CRYPTO": ("I", "H", "A"),
    "STREAM": ("Z", "A"),
    "RESET_STREAM": ("Z", "A"),
    "STOP_SENDING": ("Z", "A"),
    "HANDSHAKE_DONE": (),
    "UNKNOWN": ("I", "H", "Z", "A"),
}


def replay(tr):
    cfg = tr["config"]
    early = cfg["early"]
    overlap = cfg["overlap"]
    bufmax = cfg["buffer_packets"]
    idle_ms = cfg["idle_ms"]
    limits = {"bidi": cfg["max_streams_bidi"], "uni": cfg["max_streams_uni"]}
    msd = cfg["max_stream_data"]
    max_data = cfg["max_data"]
    clim = cfg["crypto_limit"]
    sent = cfg["sent"]

    keys = {"I": "live", "H": "absent", "Z": "live" if early else "absent",
            "A": "absent"}
    queue = {lvl: [] for lvl in LEVELS}
    pnsets = {"I": set(), "H": set(), "A": set()}
    streams = {}
    crypto = {lvl: {"highest": 0, "bytes": {}, "contig": bytearray()}
              for lvl in ("I", "H", "A")}
    received_total = 0
    state = "open"
    code = at_ms = source = peer = None
    last_activity = 0
    out = []
    qcount = [0]

    def stream(sid):
        if sid not in streams:
            streams[sid] = {"highest": 0, "final_size": None, "reset": False,
                            "stopped": False, "bytes": {},
                            "delivered": bytearray()}
        return streams[sid]

    def drop_queue(lvl, reason, at):
        for (ei, pi, _ta, _pk) in queue[lvl]:
            out.append((ei, pi, "dropped", reason, at, None))
        qcount[0] -= len(queue[lvl])
        queue[lvl] = []

    def terminate(st, cd, at, src, peer_code):
        nonlocal state, code, at_ms, source, peer
        state = st
        code = cd
        at_ms = at
        source = src
        peer = peer_code
        for lvl in LEVELS:
            drop_queue(lvl, "CONNECTION_CLOSED", at)

    def res(ei, pi, status, reason, at, frame):
        out.append((ei, pi, status, reason, at, frame))

    def check_stream_dir(sid, kind):
        mod = sid % 4
        if kind == "STOP_SENDING":
            if mod != 0:
                return "STREAM_STATE_ERROR"
            if sid // 4 + 1 > limits["bidi"]:
                return "STREAM_LIMIT_ERROR"
            return None
        if mod not in (0, 2):
            return "STREAM_STATE_ERROR"
        if sid // 4 + 1 > limits["bidi" if mod == 0 else "uni"]:
            return "STREAM_LIMIT_ERROR"
        return None

    def process(ei, pi, pk, t):
        nonlocal state, code, at_ms, source, peer, received_total, last_activity
        lvl = pk["level"]
        pn = pk["pn"]
        frames = pk["frames"]
        space = "A" if lvl in ("Z", "A") else lvl
        if not pk["auth"]:
            res(ei, pi, "dropped", "AUTH", t, None)
            return
        if pn in pnsets[space]:
            res(ei, pi, "duplicate", "DUPLICATE", t, None)
            return
        if len(frames) == 0:
            res(ei, pi, "error", "FRAME_ENCODING_ERROR", t, None)
            terminate("closed", "FRAME_ENCODING_ERROR", t,
                      {"event": ei, "packet": pi, "frame": None}, None)
            return
        for fi, f in enumerate(frames):
            if f["type"] == "UNKNOWN":
                res(ei, pi, "error", "FRAME_ENCODING_ERROR", t, fi)
                terminate("closed", "FRAME_ENCODING_ERROR", t,
                          {"event": ei, "packet": pi, "frame": fi}, None)
                return
        for fi, f in enumerate(frames):
            allowed = WL[f["type"]]
            if f["type"] == "CLOSE" and not f["app"]:
                allowed = ("I", "H", "Z", "A")
            if lvl not in allowed:
                res(ei, pi, "error", "PROTOCOL_VIOLATION", t, fi)
                terminate("closed", "PROTOCOL_VIOLATION", t,
                          {"event": ei, "packet": pi, "frame": fi}, None)
                return
        saved = (copy.deepcopy(streams), copy.deepcopy(crypto),
                 received_total)
        close_fi = None
        for fi, f in enumerate(frames):
            ty = f["type"]
            err = None
            if ty in ("PADDING", "PING"):
                continue
            if ty == "ACK":
                rngs = f["ranges"]
                if not rngs:
                    err = "FRAME_ENCODING_ERROR"
                else:
                    prev = None
                    for lo, hi in rngs:
                        if lo > hi or (prev is not None and lo <= prev + 1):
                            err = "FRAME_ENCODING_ERROR"
                            break
                        prev = hi
                    if err is None:
                        for lo, hi in rngs:
                            ok = any(slo <= lo and hi <= shi
                                     for slo, shi in sent[space])
                            if not ok:
                                err = "PROTOCOL_VIOLATION"
                                break
            elif ty == "CRYPTO":
                off = f["offset"]
                data = bytes.fromhex(f["data_hex"])
                end = off + len(data)
                cs = crypto[lvl]
                if end > MAXN:
                    err = "FRAME_ENCODING_ERROR"
                elif end > clim:
                    err = "CRYPTO_BUFFER_EXCEEDED"
                else:
                    cs["highest"] = max(cs["highest"], end)
                    for i, b in enumerate(data):
                        p = off + i
                        if p in cs["bytes"]:
                            if cs["bytes"][p] != b and overlap == "reject":
                                err = "PROTOCOL_VIOLATION"
                                break
                        else:
                            cs["bytes"][p] = b
                    if err is None:
                        pos = len(cs["contig"])
                        while pos in cs["bytes"]:
                            cs["contig"].append(cs["bytes"][pos])
                            pos += 1
            elif ty == "STREAM":
                sid = f["id"]
                err = check_stream_dir(sid, ty)
                if err is None:
                    st = stream(sid)
                    off = f["offset"]
                    data = bytes.fromhex(f["data_hex"])
                    fin = f["fin"]
                    end = off + len(data)
                    if end > MAXN:
                        err = "FRAME_ENCODING_ERROR"
                    elif st["final_size"] is not None and (
                            end > st["final_size"] or (fin and end != st["final_size"])):
                        err = "FINAL_SIZE_ERROR"
                    elif fin and end < st["highest"]:
                        err = "FINAL_SIZE_ERROR"
                    elif end > msd:
