# ---- result / termination ------------------------------------------

def res(self, ei, pi, status, reason, at, frame):
    self.results.append((ei, pi, status, reason, at, frame))

def terminate(self, state, code, at, source, peer_code):
    self.state = state
    self.code = code
    self.at_ms = at
    self.source = source
    self.peer_code = peer_code
    for lvl in LEVELS:
        self.drop_queue(lvl, "CONNECTION_CLOSED", at)

def drop_queue(self, lvl, reason, at):
    items = self.queue[lvl]
    if not items:
        return
    self.queue[lvl] = []
    self.qcount -= len(items)
    for item in items:
        self.res(item[0], item[1], "dropped", reason, at, None)

# ---- events ---------------------------------------------------------

def run(self):
    ei = 0
    for ev in self.events:
        kind = ev[0]
        t = ev[1]
        if self.state == "open" and self.idle_ms:
            deadline = self.last_activity + self.idle_ms
            if t >= deadline:
                self.terminate("idle", "IDLE_TIMEOUT", deadline,
                               (ei, None, None), None)
        if kind == "dg":
            self.do_datagram(ei, ev)
        elif self.state == "open" and kind == "k":
            self.do_key(ev, t)
        ei += 1
    for lvl in LEVELS:
        for item in self.queue[lvl]:
            self.res(item[0], item[1], "buffered", "NO_KEYS", item[2],
                     None)
    self.queue = {"I": [], "H": [], "Z": [], "A": []}
    self.qcount = 0

def do_key(self, ev, t):
    lvl = ev[2]
    if ev[3] == "discard":
        self.keys[lvl] = "discarded"
        self.drop_queue(lvl, "KEYS_DISCARDED", t)
    elif self.keys[lvl] == "absent":
        self.keys[lvl] = "live"
        items = self.queue[lvl]
        if items:
            self.queue[lvl] = []
            self.qcount -= len(items)
            for item in items:
                if self.state != "open":
                    self.res(item[0], item[1], "dropped",
                             "CONNECTION_CLOSED", t, None)
                    continue
                self.handle_packet(item[0], item[1], item[3], t)

def do_datagram(self, ei, ev):
    t = ev[1]
    size = ev[2]
    pkts = ev[3]
    n = len(pkts)
    if self.state == "open":
        for pi in range(n - 1):
            if pkts[pi][0] == "A":
                for pj in range(n):
                    self.res(ei, pj, "dropped", "LAYOUT", t, None)
                return
    for pi in range(n):
        pkt = pkts[pi]
        if self.state != "open":
            self.res(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
            continue
        lvl = pkt[0]
        if lvl == "I" and size < 1200:
            self.res(ei, pi, "dropped", "INITIAL_TOO_SMALL", t, None)
            continue
        if lvl == "Z" and not self.early:
            self.res(ei, pi, "dropped", "EARLY_REJECTED", t, None)
            continue
        ks = self.keys[lvl]
        if ks == "discarded":
            self.res(ei, pi, "dropped", "KEYS_DISCARDED", t, None)
            continue
        if ks == "absent":
            if self.qcount < self.bufmax:
                self.queue[lvl].append((ei, pi, t, pkt))
                self.qcount += 1
            else:
                self.res(ei, pi, "dropped", "BUFFER_FULL", t, None)
            continue
        self.handle_packet(ei, pi, pkt, t)

# ---- packets --------------------------------------------------------

def handle_packet(self, ei, pi, pkt, t):
    lvl, space, pn, auth, frames = pkt
    if not auth:
        self.res(ei, pi, "dropped", "AUTH", t, None)
        return
    pset = self.pnsets[space]
    if pn in pset:
        self.res(ei, pi, "duplicate", "DUPLICATE", t, None)
        return
    if not frames:
        self.packet_error(ei, pi, t, "FRAME_ENCODING_ERROR", None)
        return
    for fi in range(len(frames)):
        if frames[fi][0] == "un":
            self.packet_error(ei, pi, t, "FRAME_ENCODING_ERROR", fi)
            return
    ok_levels = ALLOWED
    for fi in range(len(frames)):
        tag = frames[fi][0]
        if tag == "cl":
            tag = "cl1" if frames[fi][1] else "cl0"
        if lvl not in ok_levels[tag]:
            self.packet_error(ei, pi, t, "PROTOCOL_VIOLATION", fi)
            return
    self.txid += 1
    self.journal = []
    self.snap_st = {}
    self.snap_cs = {}
    saved_total = self.received_total
    close_fi = -1
    for fi in range(len(frames)):
        fr = frames[fi]
        tag = fr[0]
        if tag == "pad" or tag == "ping" or tag == "hd":
            continue
        if tag == "cl":
            close_fi = fi
            break
        if tag == "ack":
            err = self.frame_ack(fr, space, fi)
        elif tag == "cry":
            err = self.frame_crypto(fr, lvl, fi)
        elif tag == "str":
            err = self.frame_stream(fr, fi)
        elif tag == "rs":
            err = self.frame_reset(fr, fi)
        else:
            err = self.frame_stop(fr, fi)
        if err is not None:
            self.rollback(saved_total)
            self.packet_error(ei, pi, t, err, fi)
            return
    pset.add(pn)
    self.last_activity = t
    self.res(ei, pi, "accepted", "OK", t, None)
    if close_fi >= 0:
        fr = frames[close_fi]
        if fr[1]:
            name = "PEER_APPLICATION_CLOSE"
        else:
            name = "PEER_TRANSPORT_CLOSE"
        self.terminate("closed", name, t, (ei, pi, close_fi), fr[2])

def packet_error(self, ei, pi, t, code, frame):
    self.res(ei, pi, "error", code, t, frame)
    self.terminate("closed", code, t, (ei, pi, frame), None)

