def _parse_packet(p, counts):
    _keys_exact(p, ("level", "pn", "auth", "frames"))
    lvl = p["level"]
    if type(lvl) is not str or lvl not in LEVELS:
        raise Bad()
    if not _dom_int(p["pn"]):
        raise Bad()
    if type(p["auth"]) is not bool:
        raise Bad()
    frames = p["frames"]
    if type(frames) is not list or len(frames) > LIM_PKT_FRAMES:
        raise Bad()
    counts[1] += 1
    if counts[1] > LIM_PACKETS:
        raise Bad()
    out = []
    for fr in frames:
        counts[2] += 1
        if counts[2] > LIM_FRAMES:
            raise Bad()
        out.append(_parse_frame(fr, counts))
    return (lvl, SPACE_OF[lvl], p["pn"], p["auth"], tuple(out))


def _parse_event(e, counts, prev_t):
    if type(e) is not dict:
        raise Bad()
    ty = e.get("op")
    if type(ty) is not str:
        raise Bad()
    if "t" not in e:
        raise Bad()
    t = e["t"]
    if not _bounded_int(t, MAXT) or t < prev_t:
        raise Bad()
    if ty == "tick":
        _keys_exact(e, ("t", "op"))
        counts[0] += 1
        return ("tk", t)
    if ty == "key":
        _keys_exact(e, ("t", "op", "level", "action"))
        lvl = e["level"]
        act = e["action"]
        if type(lvl) is not str or lvl not in LEVELS:
            raise Bad()
        if act != "install" and act != "discard":
            raise Bad()
        counts[0] += 1
        return ("k", t, lvl, act)
    if ty == "datagram":
        _keys_exact(e, ("t", "op", "bytes", "packets"))
        size = e["bytes"]
        if not _bounded_int(size, 65535):
            raise Bad()
        pkts = e["packets"]
        if type(pkts) is not list or not (1 <= len(pkts) <= LIM_DG_PKTS):
            raise Bad()
        parsed = tuple(_parse_packet(p, counts) for p in pkts)
        counts[0] += 1
        return ("dg", t, size, parsed)
    raise Bad()


def _parse_config(c):
    cfg = _keys_exact(c, ("early", "overlap", "buffer_packets", "idle_ms",
                          "max_streams_bidi", "max_streams_uni",
                          "max_stream_data", "max_data", "crypto_limit",
                          "sent"))
    early = cfg["early"]
    if type(early) is not bool:
        raise Bad()
    ov = cfg["overlap"]
    if ov != "reject" and ov != "first":
        raise Bad()
    if not _bounded_int(cfg["buffer_packets"], 1024):
        raise Bad()
    if not _bounded_int(cfg["idle_ms"], 1000000000):
        raise Bad()
    if not _bounded_int(cfg["max_streams_bidi"], 1024):
        raise Bad()
    if not _bounded_int(cfg["max_streams_uni"], 1024):
        raise Bad()
    if not _bounded_int(cfg["max_stream_data"], 65536):
        raise Bad()
    if not _dom_int(cfg["max_data"]):
        raise Bad()
    if not _bounded_int(cfg["crypto_limit"], 65536):
        raise Bad()
    sent = _keys_exact(cfg["sent"], ("I", "H", "A"))
    spaces = {}
    for lvl in CLEVELS:
        rngs = _parse_ranges_cfg(sent[lvl])
        spaces[lvl] = (tuple(r[0] for r in rngs), rngs)
    return {
        "early": early,
        "reject": ov == "reject",
        "buffer_packets": cfg["buffer_packets"],
        "idle_ms": cfg["idle_ms"],
        "msb": cfg["max_streams_bidi"],
        "msu": cfg["max_streams_uni"],
        "msd": cfg["max_stream_data"],
        "max_data": cfg["max_data"],
        "crypto_limit": cfg["crypto_limit"],
        "sent": spaces,
    }


def _parse_trace(tr, counts):
    t = _keys_exact(tr, ("id", "config", "events"))
    tid = t["id"]
    if type(tid) is not str or not ID_RE.match(tid):
        raise Bad()
    cfg = _parse_config(t["config"])
    events = t["events"]
    if type(events) is not list:
        raise Bad()
    out = []
    prev_t = 0
    for e in events:
        ev = _parse_event(e, counts, prev_t)
        prev_t = ev[1]
        out.append(ev)
        if counts[0] > LIM_EVENTS:
            raise Bad()
    return (tid, cfg, tuple(out))


